#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

using ll = long long;

int n, m, k;
bool edge[10][10];

ll determinant(vector<vector<ll>> a) {
    int size = (int)a.size();
    if (size == 0) return 1;

    ll sign = 1, previous = 1;

    for (int col = 0; col + 1 < size; ++col) {
        int pivot = col;
        while (pivot < size && a[pivot][col] == 0) ++pivot;
        if (pivot == size) return 0;

        if (pivot != col) {
            swap(a[pivot], a[col]);
            sign = -sign;
        }

        ll current = a[col][col];
        for (int i = col + 1; i < size; ++i) {
            for (int j = col + 1; j < size; ++j) {
                a[i][j] =
                    (a[i][j] * current - a[i][col] * a[col][j]) /
                    previous;
            }
        }

        previous = current;
    }

    return sign * a[size - 1][size - 1];
}

ll spanningTrees(int mask) {
    vector<int> vertices;
    for (int i = 0; i < n; ++i)
        if (mask & (1 << i))
            vertices.push_back(i);

    int size = (int)vertices.size();
    if (size <= 1) return 1;

    vector<vector<ll>> laplacian(size, vector<ll>(size));

    for (int i = 0; i < size; ++i) {
        for (int j = i + 1; j < size; ++j) {
            if (edge[vertices[i]][vertices[j]]) {
                ++laplacian[i][i];
                ++laplacian[j][j];
                laplacian[i][j] = laplacian[j][i] = -1;
            }
        }
    }

    vector<vector<ll>> minor(size - 1, vector<ll>(size - 1));
    for (int i = 0; i < size - 1; ++i)
        for (int j = 0; j < size - 1; ++j)
            minor[i][j] = laplacian[i][j];

    return determinant(minor);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m >> k;

    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        if (a != b)
            edge[a][b] = edge[b][a] = true;
    }

    int totalMasks = 1 << n;
    vector<ll> bounded(totalMasks), exact(totalMasks);

    if (n == 1) {
        bounded[0] = 1;
    } else if (n == 2 && edge[0][1]) {
        bounded[0] = 1;
    }

    for (int mask = 1; mask < totalMasks; ++mask) {
        ll ways = spanningTrees(mask);

        for (int vertex = 0; vertex < n && ways != 0; ++vertex) {
            if (mask & (1 << vertex)) continue;

            int attachments = 0;
            for (int parent = 0; parent < n; ++parent)
                if ((mask & (1 << parent)) && edge[vertex][parent])
                    ++attachments;

            ways *= attachments;
        }

        bounded[mask] = ways;
    }

    for (int mask = 0; mask < totalMasks; ++mask) {
        exact[mask] = bounded[mask];
        for (int submask = (mask - 1) & mask; submask;
             submask = (submask - 1) & mask) {
            exact[mask] -= exact[submask];
        }
        if (mask != 0)
            exact[mask] -= exact[0];
    }

    int requiredNonLeaves = n - k;
    ll answer = 0;

    if (0 <= requiredNonLeaves && requiredNonLeaves <= n) {
        for (int mask = 0; mask < totalMasks; ++mask)
            if (__builtin_popcount((unsigned)mask) == requiredNonLeaves)
                answer += exact[mask];
    }

    cout << answer << '\n';
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

int64 determinant(vector<vector<int64>> a) {
    const int n = static_cast<int>(a.size());
    if (n == 0) return 1;
    if (n == 1) return a[0][0];

    int sign = 1;
    int64 previous = 1;

    for (int k = 0; k + 1 < n; ++k) {
        int pivotRow = k;
        while (pivotRow < n && a[pivotRow][k] == 0) ++pivotRow;
        if (pivotRow == n) return 0;

        if (pivotRow != k) {
            swap(a[pivotRow], a[k]);
            sign = -sign;
        }

        const int64 pivot = a[k][k];

        for (int i = k + 1; i < n; ++i) {
            for (int j = k + 1; j < n; ++j) {
                i128 value = static_cast<i128>(a[i][j]) * pivot
                           - static_cast<i128>(a[i][k]) * a[k][j];
                value /= previous;
                a[i][j] = static_cast<int64>(value);
            }
            a[i][k] = 0;
        }

        previous = pivot;
    }

    return sign * a[n - 1][n - 1];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    cin >> n >> m >> k;

    vector<vector<int>> edge(n, vector<int>(n));
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        edge[a][b] = edge[b][a] = 1;
    }

    const int root = n - 1;
    const int nonRootCount = n - 1;
    const int requiredNonLeaves = nonRootCount - k;

    if (requiredNonLeaves < 0 || requiredNonLeaves > nonRootCount) {
        cout << 0 << '\n';
        return 0;
    }

    const int totalMasks = 1 << nonRootCount;
    vector<int64> count(totalMasks);

    for (int mask = 0; mask < totalMasks; ++mask) {
        vector<vector<int64>> laplacian(nonRootCount,
                                        vector<int64>(nonRootCount));

        for (int u = 0; u < nonRootCount; ++u) {
            for (int v = 0; v < n; ++v) {
                if (!edge[u][v]) continue;

                const int64 weight =
                    (v == root || (mask & (1 << v))) ? 1 : 0;

                laplacian[u][u] += weight;
                if (v != root) laplacian[u][v] -= weight;
            }
        }

        count[mask] = determinant(laplacian);
    }

    for (int bit = 0; bit < nonRootCount; ++bit) {
        for (int mask = 0; mask < totalMasks; ++mask) {
            if (mask & (1 << bit)) {
                count[mask] -= count[mask ^ (1 << bit)];
            }
        }
    }

    int64 answer = 0;
    for (int mask = 0; mask < totalMasks; ++mask) {
        if (__builtin_popcount(static_cast<unsigned>(mask)) ==
            requiredNonLeaves) {
            answer += count[mask];
        }
    }

    cout << answer << '\n';
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

using int64 = long long;

int64 determinant(vector<vector<int64>> a) {
    const int n = static_cast<int>(a.size());
    if (n == 0) return 1;

    int64 sign = 1;
    int64 denominator = 1;

    for (int k = 0; k + 1 < n; ++k) {
        int pivot = k;
        while (pivot < n && a[pivot][k] == 0) ++pivot;
        if (pivot == n) return 0;

        if (pivot != k) {
            swap(a[pivot], a[k]);
            sign = -sign;
        }

        const int64 pivotValue = a[k][k];

        for (int i = k + 1; i < n; ++i) {
            for (int j = k + 1; j < n; ++j) {
                a[i][j] =
                    (a[i][j] * pivotValue - a[i][k] * a[k][j]) /
                    denominator;
            }
        }

        denominator = pivotValue;
    }

    return sign * a[n - 1][n - 1];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    cin >> n >> m >> k;

    vector<vector<int>> edge(n, vector<int>(n, 0));
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        edge[a][b] = edge[b][a] = 1;
    }

    const int internalCount = n - k;
    if (internalCount < 0 || internalCount > n) {
        cout << 0 << '\n';
        return 0;
    }

    vector<vector<int64>> choose(n + 1, vector<int64>(n + 1, 0));
    for (int i = 0; i <= n; ++i) {
        choose[i][0] = choose[i][i] = 1;
        for (int j = 1; j < i; ++j)
            choose[i][j] = choose[i - 1][j - 1] + choose[i - 1][j];
    }

    const int totalMasks = 1 << n;
    vector<int64> forcedLeaves(totalMasks, 0);

    if (n == 1) {
        forcedLeaves[0] = 1;
    } else if (n == 2 && edge[0][1]) {
        forcedLeaves[0] = 1;
    }

    for (int mask = 1; mask < totalMasks; ++mask) {
        vector<int> vertices;
        for (int i = 0; i < n; ++i)
            if (mask & (1 << i))
                vertices.push_back(i);

        const int size = static_cast<int>(vertices.size());
        int64 treeCount = 1;

        if (size >= 2) {
            vector<vector<int64>> laplacian(size, vector<int64>(size, 0));

            for (int i = 0; i < size; ++i) {
                for (int j = i + 1; j < size; ++j) {
                    if (edge[vertices[i]][vertices[j]]) {
                        ++laplacian[i][i];
                        ++laplacian[j][j];
                        --laplacian[i][j];
                        --laplacian[j][i];
                    }
                }
            }

            vector<vector<int64>> minor(
                size - 1, vector<int64>(size - 1, 0)
            );

            for (int i = 0; i + 1 < size; ++i)
                for (int j = 0; j + 1 < size; ++j)
                    minor[i][j] = laplacian[i][j];

            treeCount = determinant(minor);
        }

        if (treeCount == 0) continue;

        for (int vertex = 0; vertex < n; ++vertex) {
            if (mask & (1 << vertex)) continue;

            int neighbors = 0;
            for (int inside : vertices)
                neighbors += edge[vertex][inside];

            treeCount *= neighbors;
            if (treeCount == 0) break;
        }

        forcedLeaves[mask] = treeCount;
    }

    int64 answer = 0;

    for (int mask = 0; mask < totalMasks; ++mask) {
        const int size = __builtin_popcount(static_cast<unsigned>(mask));
        if (size > internalCount) continue;

        int64 contribution =
            forcedLeaves[mask] * choose[n - size][internalCount - size];

        if ((internalCount - size) & 1)
            answer -= contribution;
        else
            answer += contribution;
    }

    cout << answer << '\n';
    return 0;
}

